select pg_advisory_xact_lock_shared(
    ('x' || substr(md5($1), 1, 16))::bit(64)::bigint
  ), 'computed' as lock_scope

select pg_advisory_xact_lock(k.lock_key), 'computed' as lock_scope
  from (
    select ('x' || substr(md5(t.key), 1, 16))::bit(64)::bigint as lock_key
    from unnest($1::text[]) with ordinality as t(key, ord)
    order by t.ord
  ) k

